<template>
  <view class="apply-change">
    <view class="nav-header">
      <view class="back-btn" @click="goBack">
        <text class="back-icon">&#xe60e;</text>
        <text>返回</text>
      </view>
      <view class="page-title">申请调班</view>
    </view>
    
    <view class="form-container">
      <view class="form-group">
        <view class="form-label">原排班时间</view>
        <view class="form-input">
          <picker mode="selector" :range="originalSchedules" range-key="display" @change="onOriginalScheduleChange">
            <view class="picker-value">{{ selectedOriginalSchedule ? selectedOriginalSchedule.display : '请选择原排班时间' }}</view>
          </picker>
        </view>
      </view>
      
      <view class="form-group">
        <view class="form-label">新日期</view>
        <view class="form-input">
          <picker mode="date" :value="newDate" :start="today" :end="endDate" @change="onNewDateChange">
            <view class="picker-value">{{ newDate || '请选择新日期' }}</view>
          </picker>
        </view>
      </view>
      
      <view class="form-group">
        <view class="form-label">新时间段</view>
        <view class="form-input">
          <picker mode="selector" :range="timeSlots" @change="onTimeSlotChange">
            <view class="picker-value">{{ selectedTimeSlot || '请选择新时间段' }}</view>
          </picker>
        </view>
      </view>
      
      <view class="form-group">
        <view class="form-label">调班原因</view>
        <view class="form-input">
          <textarea class="reason-input" v-model="reason" placeholder="请输入调班原因" maxlength="200" />
          <view class="word-count">{{ reason.length }}/200</view>
        </view>
      </view>
      
      <button class="submit-btn" :disabled="!isFormValid" @click="submitApplication">提交申请</button>
    </view>
  </view>
</template>

<script setup>
import { ref, computed } from 'vue';
import { uniShowToast, uniNavigateBack, uniNavigateTo } from '@/utils/uniHelper';

// 获取今天的日期字符串 YYYY-MM-DD
const getTodayString = () => {
  const today = new Date();
  return today.toISOString().split('T')[0];
};

// 获取30天后的日期字符串
const getEndDateString = () => {
  const end = new Date();
  end.setDate(end.getDate() + 30);
  return end.toISOString().split('T')[0];
};

const today = getTodayString();
const endDate = getEndDateString();

// 模拟原排班数据
const originalSchedules = ref([
  { id: 1, date: '2023-06-10', timeSlot: '上午 8:00-11:30', roomNumber: 'A-101', display: '2023-06-10 上午 (A-101)' },
  { id: 2, date: '2023-06-10', timeSlot: '下午 14:00-17:30', roomNumber: 'A-102', display: '2023-06-10 下午 (A-102)' },
  { id: 3, date: '2023-06-11', timeSlot: '上午 8:00-11:30', roomNumber: 'B-201', display: '2023-06-11 上午 (B-201)' },
  { id: 4, date: '2023-06-13', timeSlot: '下午 14:00-17:30', roomNumber: 'A-103', display: '2023-06-13 下午 (A-103)' }
]);

const timeSlots = ref(['上午 8:00-11:30', '下午 14:00-17:30']);

const selectedOriginalSchedule = ref(null);
const newDate = ref('');
const selectedTimeSlot = ref('');
const reason = ref('');

const onOriginalScheduleChange = (e) => {
  selectedOriginalSchedule.value = originalSchedules.value[e.detail.value];
};

const onNewDateChange = (e) => {
  newDate.value = e.detail.value;
};

const onTimeSlotChange = (e) => {
  selectedTimeSlot.value = timeSlots.value[e.detail.value];
};

const isFormValid = computed(() => {
  return selectedOriginalSchedule.value && 
         newDate.value && 
         selectedTimeSlot.value && 
         reason.value.trim().length > 0;
});

const submitApplication = async () => {
  if (!isFormValid.value) {
    await uniShowToast({ title: '请填写完整信息', icon: 'none' });
    return;
  }
  
  // 模拟提交申请
  setTimeout(async () => {
    await uniShowToast({ title: '申请提交成功' });
    setTimeout(() => {
      uniNavigateTo({ url: '/pages/doctor/schedule/schedule' });
    }, 1500);
  }, 1000);
};

const goBack = () => {
  uniNavigateTo({ url: '/pages/doctor/schedule/schedule' });
};
</script>

<style scoped>
.apply-change {
  min-height: 100vh;
  background-color: #f5f7fa;
  padding-bottom: 30rpx;
}

.nav-header {
  position: relative;
  height: 90rpx;
  background-color: #1677ff;
  color: #fff;
  display: flex;
  align-items: center;
  padding: 0 30rpx;
}

.back-btn {
  position: absolute;
  left: 30rpx;
  display: flex;
  align-items: center;
  font-size: 28rpx;
}

.back-icon {
  font-family: "iconfont";
  margin-right: 6rpx;
}

.page-title {
  width: 100%;
  text-align: center;
  font-size: 32rpx;
  font-weight: 500;
}

.form-container {
  background-color: #fff;
  border-radius: 16rpx;
  margin: 30rpx;
  padding: 30rpx;
  box-shadow: 0 2rpx 10rpx rgba(0, 0, 0, 0.05);
}

.form-group {
  margin-bottom: 30rpx;
}

.form-label {
  font-size: 28rpx;
  color: #333;
  margin-bottom: 16rpx;
  font-weight: 500;
}

.form-input {
  position: relative;
}

.picker-value {
  height: 88rpx;
  line-height: 88rpx;
  padding: 0 24rpx;
  background-color: #f5f7fa;
  border-radius: 12rpx;
  font-size: 28rpx;
  color: #333;
}

.reason-input {
  width: 100%;
  height: 200rpx;
  padding: 24rpx;
  background-color: #f5f7fa;
  border-radius: 12rpx;
  font-size: 28rpx;
  box-sizing: border-box;
}

.word-count {
  text-align: right;
  font-size: 24rpx;
  color: #999;
  margin-top: 8rpx;
}

.submit-btn {
  margin-top: 40rpx;
  background-color: #1677ff;
  color: #fff;
  height: 88rpx;
  line-height: 88rpx;
  border-radius: 44rpx;
  font-size: 30rpx;
}

.submit-btn:disabled {
  background-color: #a5c8ff;
}
</style>